package ui

import (
	"bytes"
	_ "embed"
	"image"
	"image/png"
	"sync"

	"gioui.org/layout"
	"gioui.org/op/paint"
	"gioui.org/widget"
)

// logoPNG is the app tile without margins (generated by scripts/icongen
// from packaging/logo-source.png).
//
//go:embed assets/logo.png
var logoPNG []byte

var (
	logoOnce sync.Once
	logoOp   paint.ImageOp
)

// drawLogo draws the app logo in a size×size dp square.
func drawLogo(gtx C, size int) D {
	logoOnce.Do(func() {
		img, err := png.Decode(bytes.NewReader(logoPNG))
		if err != nil {
			img = image.NewNRGBA(image.Rect(0, 0, 1, 1))
		}
		logoOp = paint.NewImageOp(img)
		logoOp.Filter = paint.FilterLinear
	})
	s := gtx.Dp(unitDp(size))
	gtx.Constraints = layout.Exact(image.Pt(s, s))
	return widget.Image{Src: logoOp, Fit: widget.Contain, Position: layout.Center}.Layout(gtx)
}
